// 真实原受领/信件实交后，以原sender Known SAY返报；唯一Task recipe结酬与原保存点晚失败。
#define main q01_original_transaction_test_main
#include "task_personal_message_transaction_test.cpp"
#undef main
#include "resident/domains/tasks/personal_reports/task_personal_report_services.hpp"
#include "resident/domains/tasks/personal_reports/task_personal_report_receipts.hpp"
#include "resident/domains/tasks/personal_reports/task_personal_report_control.hpp"
namespace {
struct ReportFixture:PersonalFixture {
 TaskPersonalReportCatalog report_catalog;
 ReportFixture(){tasks.message_handoffs->version=4;tasks.personal_reports.emplace();auto d=ic.dialogues.back();d.id="private_sender";d.entry="report";d.nodes.front().id="report";d.nodes.front().text_key="sender_accepts_original_report";ic.dialogues.push_back(d);known_catalog.templates.push_back({"private_sender","private_sender",{"installed_actor","player"},{"installed_actor","sender"}});report_catalog.policies.push_back({"original_report","letter","private_sender","report"});}
 TaskPersonalReportState& reports(){return *tasks.personal_reports;}
 TaskPersonalReportSources report_sources(const DynamicStepInput* phase=nullptr){TaskPersonalReportSources x{sources(phase),report_catalog,reports()};x.player_before=[this,phase](Integer tick,const StableId& fact){return task_personal_report_player_before(common,family,nullptr,tick,fact,phase);};return x;}
 TaskPersonalReportServices report_services(const DynamicStepInput* phase=nullptr){return {report_sources(phase),interaction,access};}
 void report_cold(){cold();auto r=validate_task_personal_reports(report_sources());require(r.ok,"private sender full source: "+r.error.original.code);}
 void open_sender(){end_talk();for(const auto* a:{"player","sender"})common.state().actors.find(a)->location=SettlementLocation{"town","away"};OpenKnownPersonalDialogue command{"sender","private_sender"};auto q=preview_known_personal_dialogue(*known_context,"player",command);require(q.ok,"actual original sender Known quote: "+q.error.original.code);const auto before=known_state;auto open=open_known_personal_dialogue_in_candidate(common,interaction,known_state,*known_context,"player",command,q.value);require(open.ok,"actual original sender opening and SAY: "+open.error.original.code);InteractionEffect effect;effect.settlement_result=open.value;ReceiptDetails details{effect,{}};auto fresh=known_personal_dialogue_new_player_source(&before,&known_state,"player","open_known_personal_dialogue",details,common.tick());require(fresh.ok,"sender actual opening difference");auto r=actual("open_known_personal_dialogue",details);require(bind_known_personal_dialogue_player_result(common,known_state,fresh.value,"player",request,*r).ok,"sender actual opening result");require(interaction.interactions.front().node_id=="report"&&interaction.interactions.front().context.role_id.empty(),"original pump reached sender's roleless report SAY");}
 ActionCoreView report(){auto q=preview_task_personal_report(report_sources(),interaction,access,"player",{task_id});require(q.ok,"actual sender report quote: "+q.error.original.code);const auto before=reports();auto id=common.next_id("action");require(id.ok,"original report action allocation");ActionCoreView a{id.value,"report_offer","player",{"player","sender"},common.tick(),q.value.duration};ActionMutation insert;insert.kind=ActionMutation::Kind::insert;insert.action=a;require(common.apply_action(insert).ok,"real original report Action");for(const auto& who:a.participants)common.state().actors.find(who)->action_id=a.id;TaskCommand command{"report_offer","letter",q.value.sender_declaration.declaration.meeting.context};command.source_kind=task_personal_report_source_kind;TaskQuote quote;quote.duration=q.value.duration;quote.context=command.context;quote.task_id=task_id;quote.reward=q.value.reward;auto started=start_task_action(common,tasks,catalog,a,command,quote);require(started.ok,"original reward reservation writer: "+started.error.original.code);auto service=report_services();started=record_task_personal_report_start_in_candidate(common,reports(),service,q.value,a);require(started.ok,"actual sender report source: "+started.error.original.code);ReceiptDetails details{ActionStarted{a.id},{}};auto fresh=task_personal_report_new_result_sources(before,reports(),"player",task_personal_report_command,details,common.tick(),common.tick());require(fresh.ok,"true private report start difference");auto r=actual(task_personal_report_command,details);started=bind_task_personal_report_results(common,reports(),report_sources(),fresh.value,"player",request,*r,common.tick());require(started.ok,"actual report start result: "+started.error.original.code);report_cold();return a;}
 Outcome<TaskEffect> finish_business(const ActionCoreView& a,const DynamicStepInput& phase){ActionMutation patch;patch.action.id=a.id;patch.remaining_ticks=0;auto r=common.apply_action(patch);if(!r.ok)return {false,{},r.error};auto delivery=services(&phase);auto report=report_services(&phase);return finish_task_action(common,tasks,social,catalog,interaction,ic,access,*common.action(a.id),phase.to_tick,nullptr,nullptr,nullptr,nullptr,&delivery,&report);}
 TaskEffect finish(const ActionCoreView& a){const auto before_delivery=state();const auto before_report=reports();const DynamicStepInput phase{common.tick(),common.tick()+1};auto effect=finish_business(a,phase);require(effect.ok,"original Task finish with private report services: "+effect.error.original.code);tasks.actions.erase(a.id);ActionMutation erase;erase.kind=ActionMutation::Kind::erase;erase.action.id=a.id;require(common.apply_action(erase).ok,"original report Action unified release");for(const auto& who:a.participants)common.state().actors.find(who)->action_id.clear();common.state().identity.tick=phase.to_tick;ActionCompletion completion;completion.task=effect.value;AdvanceDetails advance;advance.completed_actions.insert(a.id,completion);ReceiptDetails details{advance,{}};auto delivery=task_personal_message_new_result_sources(before_delivery,state(),"player","advance",details,common.tick(),phase.from_tick);require(delivery.ok,"same result true Q01 difference");auto report=task_personal_report_new_result_sources(before_report,reports(),"player","advance",details,common.tick(),phase.from_tick);require(report.ok,"same result true report difference");auto r=actual("advance",details);auto valid=bind_task_personal_message_results(common,state(),sources(),delivery.value,"player",request,*r,phase.from_tick);require(valid.ok,"same true Advance Q01 binding: "+valid.error.original.code);valid=bind_task_personal_report_results(common,reports(),report_sources(),report.value,"player",request,*r,phase.from_tick);require(valid.ok,"same true Advance report binding: "+valid.error.original.code);report_cold();return effect.value;}
 void accepted(){require(finish(start_original("accept_offer")).success,"real original acceptance in handoff4");}
 void delivered(){accepted();open_recipient();require(finish(deliver()).success,"actual original Q01 letter reaches receiver");}
};
}
int run_personal_report_transaction_component(){try{
 ReportFixture f;f.delivered();require(!preview_task_personal_report(f.report_sources(),f.interaction,f.access,"player",{f.task_id}).ok,"recipient consent is not original sender report consent");f.open_sender();require(f.shared->roles.find("sender")->place_id=="market","original sender role was never moved");auto a=f.report();require(f.common.wallet("cash:player")->balance==100&&f.common.wallet("cash:sender")->balance==100,"report start reserves without paying");require(f.finish(a).success,"real Task reports to same sender away from original role");require(f.common.wallet("cash:player")->balance==108&&f.common.wallet("cash:sender")->balance==92,"original Task reward paid exactly once");require(f.tasks.message_handoffs->reports.size()==1&&f.tasks.message_handoffs->reports.rows().front().second.role_id.empty(),"original report carries independent private sender source");require(!preview_task_personal_report(f.report_sources(),f.interaction,f.access,"player",{f.task_id}).ok,"settled task cannot be paid twice");f.common.state().history.clear();f.common.state().results={};f.report_cold();auto kept=f.reports();f.reports().starts.find(f.reports().starts.order().front())->actual_result.reset();require(!validate_task_personal_reports(f.report_sources()).ok,"all cache pruning still requires original start result");f.reports()=kept;
 ReportFixture retry;retry.delivered();retry.open_sender();auto first=retry.report();retry.common.state().actors.find("sender")->location=SettlementLocation{"town","market"};auto interrupted=retry.finish(first);require(!interrupted.success&&!interrupted.task_id&&retry.common.wallet("cash:player")->balance==100,"absent sender preserves original optional failure and no pay");retry.open_sender();require(retry.finish(retry.report()).success&&retry.reports().starts.size()==2,"real new sender SAY retries only after original interruption");
 ReportFixture cancel;cancel.delivered();cancel.open_sender();auto unfinished=cancel.report();cancel.interaction.interactions.front().node_id="other";auto changed=cancel.finish(unfinished);require(!changed.success&&changed.code==std::optional<StableId>{"TaskPersonalReportDeclarationChanged"},"changed valid SAY is recorded interruption, not report");cancel.interaction.interactions.front().node_id="report";cancel.cancel();cancel.report_cold();require(cancel.common.wallet("cash:player")->balance==100&&cancel.tasks.message_handoffs->reports.empty(),"cancellation after actual interruption never invents report or reward");
 ReportFixture expiry;expiry.delivered();expiry.common.state().identity.tick=expiry.tasks.tasks.find(expiry.task_id)->deadline_tick+3;expiry.open_sender();require(!preview_task_personal_report(expiry.report_sources(),expiry.interaction,expiry.access,"player",{expiry.task_id}).ok,"sender statement does not extend old Task grace");
 ReportFixture late;late.delivered();late.open_sender();auto last=late.report();late.common.state().next_instance_id=std::numeric_limits<Integer>::max()-2;const auto original=encode_common_state(late.common.state());const auto tasks=late.tasks;const auto social=late.social;auto save=late.common.begin_savepoint();require(save.ok,"original Common savepoint before cash");DynamicStepInput phase{late.common.tick(),late.common.tick()+1};auto error=late.finish_business(last,phase);require(!error.ok&&error.error.original.code=="InstanceIdOverflow","new final report source fails after true payment/report allocation");require(late.common.wallet("cash:player")->balance==108,"late failure occurs after original cash recipe");require(late.common.rollback_savepoint(save.value).ok,"original Common rollback");late.tasks=tasks;late.social=social;require(compare_boundary(original,encode_common_state(late.common.state())).exact()&&late.reports().endings.empty()&&late.tasks.message_handoffs->reports.empty(),"whole Task/source/social saved candidate restored without false payment");late.report_cold();
 std::cout<<"Original sender report actual Task/Known transaction source; runtime result must be recorded separately\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}

#ifndef HANMO_PERSONAL_TASK_TRANSACTIONS_COMPONENT
int main(){return run_personal_report_transaction_component();}
#endif
